changeSet.sql:
CREATE TABLE nexus.tuples ( id BYTEA NOT NULL, tenant_id TEXT NOT NULL, subspace TEXT NOT NULL, template TEXT NOT NULL, keys JSONB NOT NULL, dims JSONB, body TEXT, claim_state TEXT, claimant TEXT, claim_id TEXT, lease_until TIMESTAMPTZ, attempts INTEGER NOT NULL DEFAULT 0, consumed_at TIMESTAMPTZ, consumed_by TEXT, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, CONSTRAINT tuples_pk PRIMARY KEY (id) );
-- Claim-scan predicate every in/inp walks: unconsumed, unclaimed rows for -- a (tenant, subspace), oldest first. CREATE INDEX idx_tuples_claim_scan ON nexus.tuples (tenant_id, subspace, created_at) WHERE consumed_at IS NULL AND claim_state IS NULL;
ALTER TABLE nexus.tuples SET (autovacuum_vacuum_scale_factor = 0.01);
ALTER TABLE nexus.tuples ENABLE ROW LEVEL SECURITY; ALTER TABLE nexus.tuples FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation ON nexus.tuples USING (tenant_id = current_setting('nexus.tenant', true)) WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON nexus.tuples;
ALTER TABLE nexus.tuples NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuples DISABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuples RESET (autovacuum_vacuum_scale_factor);
DROP INDEX IF EXISTS nexus.idx_tuples_claim_scan;
DROP TABLE IF EXISTS nexus.tuples CASCADE;

changeSet.sql:
CREATE TABLE nexus.tuple_claim_log ( log_id BIGSERIAL NOT NULL, tenant_id TEXT NOT NULL, subspace TEXT NOT NULL, template TEXT NOT NULL, tuple_id BYTEA, claim_id TEXT, claimant TEXT, transition TEXT NOT NULL, at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, CONSTRAINT tuple_claim_log_pk PRIMARY KEY (log_id), CONSTRAINT tuple_claim_log_tuple_fk FOREIGN KEY (tuple_id) REFERENCES nexus.tuples (id) ON DELETE SET NULL );
-- FK-enforcement + purge lookup path (file header: "the purge deletes -- through it"). CREATE INDEX idx_tuple_claim_log_tuple_id ON nexus.tuple_claim_log (tuple_id);
ALTER TABLE nexus.tuple_claim_log SET (autovacuum_vacuum_scale_factor = 0.01);
ALTER TABLE nexus.tuple_claim_log ENABLE ROW LEVEL SECURITY; ALTER TABLE nexus.tuple_claim_log FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation ON nexus.tuple_claim_log USING (tenant_id = current_setting('nexus.tenant', true)) WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON nexus.tuple_claim_log;
ALTER TABLE nexus.tuple_claim_log NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuple_claim_log DISABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuple_claim_log RESET (autovacuum_vacuum_scale_factor);
DROP INDEX IF EXISTS nexus.idx_tuple_claim_log_tuple_id;
DROP TABLE IF EXISTS nexus.tuple_claim_log CASCADE;
